/*Function: dbo.f_get_char_byindex
**Copyright (c) ---------------Dongguan Zensee Printing Ltd----------------
**Creator: IT_Micro.
**Create date: 2006/12/20
**Modify: 
**Modify date: 
**Description:
	該函數是把傳入字串按指定的分隔符號分割,然後按傳入的index取相對位置的字串
	例如：
			abc,hje,keur,geeip,hje,abc,irk
	傳入index=3時:
			返回結果:keur
	傳入index=5時:
			返回結果:hje
	傳入index>7時
			返回結果:null(如果傳入的index大於字串的最大分割符數量時返回null)

**Parameters: 	
	@char_List 		type: varchar.		value: char list
	@sign			type: char	,	value: split sign
	@index			type: int,		value: char index
*/
CREATE  FUNCTION dbo.f_get_char_byindex(@char_List varchar(8000),@sign char(1),@index int)
RETURNS varchar(1000) AS  
BEGIN 
	declare @char_now varchar(8000),
		@char_split varchar(8000),
		@intpos int,
		@this_index int
	declare @return_char varchar(1000)

	set @char_now=@char_List
	set @this_index=1

	set @intpos=charindex(@sign,@char_now)
	while (@intpos>=0)
	begin
		if @intPos>0 
			set @char_split=left(@char_now,@intPos-1)
		else
			set @char_split=@char_now
			
		if @this_index=@index
		begin
			set @return_char=@char_split
			goto this
		end
		else
		begin
			set @this_index=@this_index+1
		end
		set @char_now=right(@char_now,len(@char_now)-@intPos)
		if @intPos>0
			set @intPos=charindex(@sign,@char_now)
		else
			set @intPos=-1
	end

this:
	--returns.
	return @return_char
END




GO

