--获取根节点MODULE INDEX
CREATE FUNCTION dbo.f_get_root_m_idx(@m_idx int)
RETURNS int AS  
BEGIN 
	declare @root_idx int
	select @root_idx=ISNULL(m_p_idx,-1) from MODULES where m_idx=@m_idx
	if @root_idx = -1 or @root_idx = 0  or @root_idx = @m_idx
